{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Omadacycline, a complex polycyclic natural-product antibiotic, has an absolute oral bioavailability of 34.5% in healthy adults, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "9-Nitrocamptothecin, a lipophilic lactone-containing natural product, has very low absolute oral bioavailability in patients, which would argue for low F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "5-Hydroxyrofecoxib has an oral bioavailability of 0.140 in healthy subjects, below the 20% threshold, providing a low-F counterexample.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The highest-transfer evidence (omadacycline, F=34.5% in humans) supports high oral bioavailability; low-F analogues are less transferable or involve dissimilar polar/ionizable scaffolds, and the query's small lipophilic lactone profile is consistent with absorption. Overall F ≥ 20% is better supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the query molecule.",
    "Uncertainty about lactone stability and first-pass metabolism in humans.",
    "Extrapolation from rat/human analogues with different scaffolds."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

